mapper.select:
SELECT * FROM stock_control
WHERE deleted = 0

      AND create_time >= #{startTime}


      AND create_time <= #{endTime}


      AND station_id = #{stationId}

SELECT sc.card_id AS cardId, cc.type AS type, COUNT(*) AS count
FROM stock_control sc
LEFT JOIN card_config cc ON sc.card_id = cc.id AND cc.deleted = 0
WHERE sc.deleted = 0

      AND sc.create_time >= #{startTime}


      AND sc.create_time <= #{endTime}


      AND sc.station_id = #{stationId}

GROUP BY sc.card_id

SELECT DATE(create_time) AS date, SUM(current_stock) AS count
FROM stock_control
WHERE deleted = 0

      AND create_time >= #{startTime}


      AND create_time <= #{endTime}


      AND station_id = #{stationId}

GROUP BY DATE(create_time)
ORDER BY DATE(create_time) ASC

SELECT * FROM stock_control
WHERE deleted = 0 AND card_id = #{cardId} AND station_id = #{stationId}
LIMIT 1
